using System;using System.Data;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmSemesterResults:StyledForm {
 DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};ComboBox student=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};TextBox year=new TextBox();NumericUpDown semester=new NumericUpDown{Minimum=1,Maximum=12,Value=1};CheckBox passed=new CheckBox{Text="Passed",Checked=true,AutoSize=true};DateTimePicker date=new DateTimePicker();int id;
 public FrmSemesterResults(){Text="Semester Results";Size=new Size(1100,650);Controls.Add(g);var e=new TableLayoutPanel{Dock=DockStyle.Right,Width=320,Padding=new Padding(18),ColumnCount=1};e.Controls.Add(new Label{Text="Result Record",Font=new Font("Segoe UI",15,FontStyle.Bold),AutoSize=true});Add(e,"Student",student);Add(e,"Academic year",year);Add(e,"Semester",semester);e.Controls.Add(passed);Add(e,"Result date",date);var save=new Button{Text="Save Result",Width=145,Height=38};var clear=UiTheme.Secondary("New / Clear");var del=UiTheme.Secondary("Delete");e.Controls.Add(save);e.Controls.Add(clear);e.Controls.Add(del);Controls.Add(e);Controls.Add(UiTheme.Heading("Semester Results","Latest result controls continuing-student eligibility"));student.DisplayMember="Display";student.ValueMember="StudentId";LoadStudents();Clear();LoadData();g.SelectionChanged+=delegate{LoadSelected();};clear.Click+=delegate{Clear();};save.Click+=delegate{try{if(student.SelectedValue==null)throw new ArgumentException("Select a student.");new ResultQuery().Save(id,Convert.ToInt32(student.SelectedValue),year.Text.Trim(),Convert.ToInt32(semester.Value),passed.Checked,date.Value.Date);LoadData();Clear();}catch(Exception ex){MessageBox.Show(ex.Message,"Unable to save");}};del.Click+=delegate{if(id>0&&MessageBox.Show("Delete this result?","Confirm",MessageBoxButtons.YesNo)==DialogResult.Yes){new ResultQuery().Delete(id);LoadData();Clear();}};}
 void Add(TableLayoutPanel p,string label,Control c){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(3,10,3,2)});c.Width=260;p.Controls.Add(c);}void LoadStudents(){var t=new ResultQuery().Students();t.Columns.Add("Display",typeof(string));foreach(DataRow r in t.Rows)r["Display"]=r["StudentName"]+" - "+r["UniversityRollNo"];student.DataSource=t;}void LoadData(){g.DataSource=new ResultQuery().All();if(g.Columns.Contains("StudentId"))g.Columns["StudentId"].Visible=false;if(g.Columns.Contains("ResultId"))g.Columns["ResultId"].Visible=false;}void LoadSelected(){if(g.CurrentRow==null||g.CurrentRow.IsNewRow||g.CurrentRow.Cells["ResultId"].Value==null||g.CurrentRow.Cells["ResultId"].Value==DBNull.Value)return;id=Convert.ToInt32(g.CurrentRow.Cells["ResultId"].Value);if(g.CurrentRow.Cells["StudentId"].Value!=DBNull.Value)student.SelectedValue=Convert.ToInt32(g.CurrentRow.Cells["StudentId"].Value);year.Text=Convert.ToString(g.CurrentRow.Cells["AcademicYear"].Value);if(g.CurrentRow.Cells["Semester"].Value!=DBNull.Value)semester.Value=Convert.ToDecimal(g.CurrentRow.Cells["Semester"].Value);passed.Checked=g.CurrentRow.Cells["IsPassed"].Value!=DBNull.Value&&Convert.ToBoolean(g.CurrentRow.Cells["IsPassed"].Value);if(g.CurrentRow.Cells["ResultDate"].Value!=DBNull.Value)date.Value=Convert.ToDateTime(g.CurrentRow.Cells["ResultDate"].Value);}void Clear(){id=0;year.Text=new SystemSettingsQuery().Get("AcademicYear");semester.Value=1;passed.Checked=true;date.Value=DateTime.Today;}
} }
